(()=>{"use strict";
const $=id=>document.getElementById(id), euro=n=>new Intl.NumberFormat("fr-FR",{style:"currency",currency:"EUR"}).format(Number(n)||0);
const KEY="bep-spend-challenges-v1";
const challenges=[{id:"pause",icon:"⏳",title:"Le défi des 24 heures",desc:"Pour un achat non essentiel, laisse passer une journée avant de décider.",done:"Pause prise. Tu as laissé la place à une décision réfléchie."},{id:"subscriptions",icon:"🔎",title:"Le détective des abonnements",desc:"Repère un abonnement oublié, doublonné ou devenu inutile.",done:"Enquête terminée. Un petit contrôle peut éviter une dépense récurrente."},{id:"pleasure",icon:"🎈",title:"Le plaisir maîtrisé",desc:"Choisis un plaisir qui entre dans ton budget, sans culpabiliser.",done:"Plaisir planifié : c'est aussi ça, bien gérer son argent."},{id:"basket",icon:"🛍️",title:"Le panier malin",desc:"Avant de payer, retire un article dont tu n'as pas vraiment besoin.",done:"Panier passé au crible. Une décision de plus en conscience."}];
let done={};try{done=JSON.parse(localStorage.getItem(KEY)||"{}")||{}}catch{}
function readState(){try{return JSON.parse(localStorage.getItem("bep-mobile-v1")||"{}")}catch{return {}}}
function monthlyStats(){const s=readState(),now=new Date(),items=(Array.isArray(s.expenses)?s.expenses:[]).filter(p=>{const d=new Date(p.at);return d.getMonth()===now.getMonth()&&d.getFullYear()===now.getFullYear()});const total=items.reduce((n,p)=>n+Math.max(0,Number(p.amount)||0),0),impulsive=items.filter(p=>p.psychology==="impulsive"||p.psychology==="pressure").length;const categories={};items.forEach(p=>{const k=p.category||"Autre";categories[k]=(categories[k]||0)+Math.max(0,Number(p.amount)||0)});return {items,total,impulsive,categories}}
function setTab(tab){document.querySelectorAll("[data-spend-tab]").forEach(b=>{const active=b.dataset.spendTab===tab;b.setAttribute("aria-selected",String(active));});document.querySelectorAll("[data-spend-view]").forEach(v=>v.hidden=v.dataset.spendView!==tab)}
function currentScore(){const psychology=$("psychology")?.value||"reflective",need=$("need")?.value||"yes",delay=$("delay")?.value||"now",amount=Math.max(0,Number($("purchaseAmount")?.value)||0),s=readState();let score=45;score+=psychology==="reflective"?20:psychology==="spontaneous"?8:psychology==="impulsive"?-12:-20;score+=need==="yes"?20:need==="uncertain"?8:-5;score+=delay==="24h"?15:delay==="7d"?18:delay==="already_done"?5:0;const income=(Array.isArray(s.incomes)?s.incomes:[]).reduce((n,x)=>n+Math.max(0,Number(x.amount)||0),0)||Math.max(0,Number(s.income)||0),charges=(Array.isArray(s.budgets)?s.budgets:[]).reduce((n,x)=>n+Math.max(0,Number(x.amount)||0),0),remaining=income-charges;if(income>0&&amount>0){const ratio=remaining>0?amount/remaining:2;score+=ratio<=.05?15:ratio<=.15?8:ratio<=.3?0:-12}else score+=5;return Math.max(0,Math.min(100,Math.round(score)))}
function scoreCopy(score){if(score>=85)return ["Décision au top !","Ton achat semble cohérent. Garde simplement un œil sur ton enveloppe."];if(score>=70)return ["Bonne réflexion !","Quelques vérifications et tu peux décider sereinement."];if(score>=50)return ["Prends encore un instant.","Un petit recul peut t'aider à distinguer envie, besoin et budget."];return ["Attention au craquage !","La meilleure décision, pour l'instant, est peut-être de ralentir."]}
function updateScore(){const score=currentScore(),ring=$("bepSpendScoreRing"),number=$("bepSpendScoreNumber"),title=$("bepSpendScoreTitle"),desc=$("bepSpendScoreDesc"),bar=$("bepSpendScoreBar");if(!ring)return;const copy=scoreCopy(score);ring.style.setProperty("--score",score);number.textContent=String(score);title.textContent=copy[0];desc.textContent=copy[1];bar.style.width=score+"%"}
function updateHero(){const stats=monthlyStats();const amount=$("bepSpendMonthTotal"),count=$("bepSpendMonthCount"),decisions=$("bepSpendMonthDecisions");if(amount)amount.textContent=euro(stats.total);if(count)count.textContent=stats.items.length+" achat"+(stats.items.length>1?"s":"");if(decisions)decisions.textContent=stats.impulsive+" achat"+(stats.impulsive>1?"s":"")+" sous impulsion"}
function renderChallenges(){const host=$("bepSpendChallengeGrid");if(!host)return;host.innerHTML=challenges.map(c=>'<article class="bep-spend-challenge '+(done[c.id]?"is-done":"")+'"><span class="bep-spend-challenge-icon" aria-hidden="true">'+c.icon+'</span><b>'+c.title+'</b><p>'+c.desc+'</p><button type="button" data-spend-challenge="'+c.id+'" aria-pressed="'+Boolean(done[c.id])+'">'+(done[c.id]?"Défi validé ✓":"Je relève le défi")+'</button></article>').join("");host.querySelectorAll("[data-spend-challenge]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.spendChallenge;done[id]=!done[id];try{localStorage.setItem(KEY,JSON.stringify(done))}catch{}renderChallenges()}));const status=$("bepSpendChallengeStatus");if(status){const n=challenges.filter(c=>done[c.id]).length;status.textContent=n+" / "+challenges.length+" défis relevés. Chaque petite décision compte."}}
function renderBalance(){const stats=monthlyStats(),avg=stats.items.length?stats.total/stats.items.length:0,rate=stats.items.length?Math.round(stats.impulsive/stats.items.length*100):0;const set=(id,v)=>{const e=$(id);if(e)e.textContent=v};set("bepSpendBalanceTotal",euro(stats.total));set("bepSpendBalanceCount",String(stats.items.length));set("bepSpendBalanceAverage",euro(avg));set("bepSpendBalanceImpulse",rate+" %");const host=$("bepSpendCategoryList");if(host){const rows=Object.entries(stats.categories).sort((a,b)=>b[1]-a[1]).slice(0,5);host.innerHTML=rows.length?rows.map(([name,value])=>'<div class="bep-spend-category-row"><span>'+name.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))+'</span><b>'+euro(value)+'</b></div>').join(""):'<div class="bep-spend-empty">Tes premières dépenses apparaîtront ici. Enregistre un achat pour commencer ton bilan.</div>'}}
function init(){const panel=$("purchases"),form=$("purchaseForm");if(!panel||!form||$("bepSpendExperience"))return;
const hero=document.createElement("section");hero.id="bepSpendExperience";hero.className="bep-spend-hero";hero.innerHTML='<div class="bep-spend-hero-top"><span class="bep-spend-kicker">LE RADAR DES BONNES DÉCISIONS</span><span class="bep-spend-pill">BEP · MODE MALIN</span></div><div class="bep-spend-hero-main"><div><h1>Avant de craquer,<br>on fait le point ?</h1><p>Un achat, une envie, une hésitation ? Prends 30 secondes pour vérifier si la dépense te ressemble vraiment.</p></div><svg class="bep-spend-mascot" viewBox="0 0 120 120" role="img" aria-label="Mascotte BEP qui observe un achat"><circle cx="60" cy="60" r="55" fill="#fff" opacity=".72"/><path d="M29 45c0-18 13-30 31-30s31 12 31 30v34c0 13-13 22-31 22S29 92 29 79Z" fill="#fff" stroke="#b9d3c2" stroke-width="3"/><rect x="23" y="43" width="74" height="45" rx="19" fill="#173f35" stroke="#d7b65e" stroke-width="4"/><rect x="31" y="50" width="58" height="31" rx="13" fill="#0b2822"/><circle cx="47" cy="64" r="4.5" fill="#76e3b7"/><circle cx="73" cy="64" r="4.5" fill="#76e3b7"/><path d="M48 73q12 7 24 0" stroke="#76e3b7" stroke-width="2.5" fill="none" stroke-linecap="round"/><path d="M60 15V7m-6 0h12" stroke="#c49a42" stroke-width="3" stroke-linecap="round"/><path d="M24 57h-8m80 0h8" stroke="#c49a42" stroke-width="4" stroke-linecap="round"/><circle cx="96" cy="25" r="12" fill="#ffdf88"/><path d="m96 18 2.2 5.1 5.5.5-4.2 3.5 1.3 5.3-4.8-2.8-4.8 2.8 1.3-5.3-4.2-3.5 5.5-.5Z" fill="#9c7628"/></svg></div><div class="bep-spend-stats"><div class="bep-spend-stat"><span>Dépensé ce mois</span><strong id="bepSpendMonthTotal">0,00 €</strong></div><div class="bep-spend-stat"><span>Achats enregistrés</span><strong id="bepSpendMonthCount">0 achat</strong></div><div class="bep-spend-stat"><span>Sous impulsion</span><strong id="bepSpendMonthDecisions">0 achat</strong></div></div>';
const nav=document.createElement("nav");nav.className="bep-spend-nav";nav.setAttribute("aria-label","Expérience dépenses");nav.innerHTML='<button type="button" data-spend-tab="radar" aria-selected="true">Mon radar</button><button type="button" data-spend-tab="challenges" aria-selected="false">Mes défis</button><button type="button" data-spend-tab="balance" aria-selected="false">Mon bilan</button>';
const score=document.createElement("div");score.className="bep-spend-score bep-spend-view";score.dataset.spendView="radar";score.innerHTML='<div class="bep-spend-score-ring" id="bepSpendScoreRing"><strong id="bepSpendScoreNumber">—</strong></div><div class="bep-spend-score-copy"><b id="bepSpendScoreTitle">Ton score de décision</b><span id="bepSpendScoreDesc">Renseigne ton achat pour obtenir un repère indicatif, sans jugement.</span><div class="bep-spend-score-track"><i id="bepSpendScoreBar"></i></div></div>';
const challenge=document.createElement("section");challenge.className="bep-spend-view";challenge.dataset.spendView="challenges";challenge.hidden=true;challenge.innerHTML='<article class="card"><div class="card-head"><div><p class="eyebrow">PETITES HABITUDES, GRANDES VICTOIRES</p><h2>Mes défis BEP</h2></div><span class="tag">À ton rythme</span></div><p class="bep-spend-challenge-status" id="bepSpendChallengeStatus"></p><div class="bep-spend-challenge-grid" id="bepSpendChallengeGrid"></div></article>';
const balance=document.createElement("section");balance.className="bep-spend-view";balance.dataset.spendView="balance";balance.hidden=true;balance.innerHTML='<article class="card"><p class="eyebrow">MON MOIS EN UN COUP D’ŒIL</p><h2>Je comprends mes habitudes</h2><div class="bep-spend-insight-grid"><div class="bep-spend-insight"><span>Total des achats enregistrés</span><strong id="bepSpendBalanceTotal">0,00 €</strong><p>Sur le mois en cours</p></div><div class="bep-spend-insight"><span>Nombre d’achats</span><strong id="bepSpendBalanceCount">0</strong><p>Achats enregistrés</p></div><div class="bep-spend-insight"><span>Panier moyen</span><strong id="bepSpendBalanceAverage">0,00 €</strong><p>Par achat</p></div><div class="bep-spend-insight"><span>Achats sous impulsion</span><strong id="bepSpendBalanceImpulse">0 %</strong><p>Spontanés difficiles à différer ou sous pression</p></div><div class="bep-spend-insight bep-spend-insight-wide"><span>Mes principaux postes</span><div class="bep-spend-category-list" id="bepSpendCategoryList"></div></div></div></article>';
panel.insertBefore(hero,panel.firstChild);panel.insertBefore(nav,hero.nextSibling);panel.insertBefore(score,nav.nextSibling);panel.insertBefore(challenge,score.nextSibling);panel.insertBefore(balance,challenge.nextSibling);
const entry=panel.querySelector(".purchase-entry-card");if(entry){const heading=entry.querySelector("h2");if(heading)heading.textContent="Je passe mon achat au radar";const intro=document.createElement("p");intro.className="bep-spend-form-intro";intro.textContent="Quelques questions simples pour distinguer besoin, envie et décision impulsive. Tes réponses alimentent le conseil BEP existant.";entry.insertBefore(intro,form);const note=document.createElement("p");note.className="bep-spend-form-note";note.textContent="Le score affiché est un repère pédagogique indicatif, pas une note morale ni une autorisation automatique de dépenser.";form.appendChild(note)}
nav.querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>setTab(b.dataset.spendTab)));
["psychology","need","delay","purchaseAmount"].forEach(id=>$(id)?.addEventListener("input",updateScore));["psychology","need","delay"].forEach(id=>$(id)?.addEventListener("change",updateScore));
form.addEventListener("submit",()=>{setTimeout(()=>{updateHero();updateBalance();updateScore()},80)});
const rows=$("purchaseRows");if(rows&&"MutationObserver"in window)new MutationObserver(()=>{updateHero();updateBalance()}).observe(rows,{childList:true,subtree:true});
renderChallenges();updateHero();updateBalance();updateScore();
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})();